// Package lru implements a fixed-capacity least-recently-used cache.
//
// Entries live in a single slice and are linked by index rather than by
// pointer, which keeps allocations low and the garbage collector idle even
// with millions of entries.
package lru

// nilIdx marks the absence of a neighbouring entry.
const nilIdx = -1

type entry struct {
	key, value string
	prev, next int32
}

// Cache is an LRU cache mapping string keys to string values.
// The zero value is not usable; create one with New.
type Cache struct {
	capacity int
	index    map[string]int32
	entries  []entry
	free     []int32 // indices of entries released by Delete
	head     int32   // most recently used
	tail     int32   // least recently used
}

// New returns an empty cache holding at most capacity keys.
// It panics if capacity is less than 1.
func New(capacity int) *Cache {
	if capacity < 1 {
		panic("lru: capacity must be at least 1")
	}
	return &Cache{
		capacity: capacity,
		index:    make(map[string]int32),
		head:     nilIdx,
		tail:     nilIdx,
	}
}

// Len reports the number of keys held.
func (c *Cache) Len() int { return len(c.index) }

// Get returns the value stored under key and marks it most recently used.
func (c *Cache) Get(key string) (string, bool) {
	i, ok := c.index[key]
	if !ok {
		return "", false
	}
	c.moveToFront(i)
	return c.entries[i].value, true
}

// Set stores value under key and marks it most recently used, evicting the
// least recently used key if the cache exceeds its capacity.
func (c *Cache) Set(key, value string) {
	if i, ok := c.index[key]; ok {
		c.entries[i].value = value
		c.moveToFront(i)
		return
	}
	if len(c.index) >= c.capacity {
		// Reuse the evicted slot directly for the new entry.
		i := c.tail
		c.unlink(i)
		delete(c.index, c.entries[i].key)
		c.entries[i].key, c.entries[i].value = key, value
		c.pushFront(i)
		c.index[key] = i
		return
	}
	i := c.alloc(key, value)
	c.pushFront(i)
	c.index[key] = i
}

// Delete removes key and reports whether it was present.
func (c *Cache) Delete(key string) bool {
	i, ok := c.index[key]
	if !ok {
		return false
	}
	c.unlink(i)
	delete(c.index, key)
	c.entries[i] = entry{} // release strings for the garbage collector
	c.free = append(c.free, i)
	return true
}

func (c *Cache) alloc(key, value string) int32 {
	if n := len(c.free); n > 0 {
		i := c.free[n-1]
		c.free = c.free[:n-1]
		c.entries[i].key, c.entries[i].value = key, value
		return i
	}
	c.entries = append(c.entries, entry{key: key, value: value})
	return int32(len(c.entries) - 1)
}

func (c *Cache) moveToFront(i int32) {
	if c.head == i {
		return
	}
	c.unlink(i)
	c.pushFront(i)
}

func (c *Cache) pushFront(i int32) {
	e := &c.entries[i]
	e.prev, e.next = nilIdx, c.head
	if c.head != nilIdx {
		c.entries[c.head].prev = i
	} else {
		c.tail = i
	}
	c.head = i
}

func (c *Cache) unlink(i int32) {
	e := &c.entries[i]
	if e.prev != nilIdx {
		c.entries[e.prev].next = e.next
	} else {
		c.head = e.next
	}
	if e.next != nilIdx {
		c.entries[e.next].prev = e.prev
	} else {
		c.tail = e.prev
	}
	e.prev, e.next = nilIdx, nilIdx
}

package lru

import "testing"

func TestEvictsLeastRecentlyUsed(t *testing.T) {
	t.Parallel()
	c := New(2)
	c.Set("a", "1")
	c.Set("b", "2")
	if v, ok := c.Get("a"); !ok || v != "1" {
		t.Fatalf(`Get("a") = %q, %v; want "1", true`, v, ok)
	}
	c.Set("c", "3")
	if _, ok := c.Get("b"); ok {
		t.Fatal(`Get("b") hit; want evicted`)
	}
	if got := c.Len(); got != 2 {
		t.Fatalf("Len() = %d, want 2", got)
	}
}

func TestOverwriteRefreshes(t *testing.T) {
	t.Parallel()
	c := New(2)
	c.Set("a", "1")
	c.Set("b", "2")
	c.Set("a", "9")
	c.Set("c", "3")
	for _, tt := range []struct {
		key, want string
		ok        bool
	}{{"a", "9", true}, {"b", "", false}, {"c", "3", true}} {
		if v, ok := c.Get(tt.key); v != tt.want || ok != tt.ok {
			t.Errorf("Get(%q) = %q, %v; want %q, %v", tt.key, v, ok, tt.want, tt.ok)
		}
	}
}

func TestDeleteReusesSlots(t *testing.T) {
	t.Parallel()
	c := New(3)
	c.Set("x", "1")
	if !c.Delete("x") {
		t.Fatal(`Delete("x") = false, want true`)
	}
	if c.Delete("x") {
		t.Fatal(`second Delete("x") = true, want false`)
	}
	if c.Len() != 0 {
		t.Fatalf("Len() = %d, want 0", c.Len())
	}
	for _, k := range []string{"p", "q", "r", "s"} {
		c.Set(k, k)
	}
	if _, ok := c.Get("p"); ok {
		t.Fatal(`Get("p") hit; want evicted`)
	}
	if len(c.entries) != 3 {
		t.Fatalf("len(entries) = %d, want 3", len(c.entries))
	}
}

func TestCapacityOne(t *testing.T) {
	t.Parallel()
	c := New(1)
	c.Set("a", "1")
	c.Set("b", "2")
	if _, ok := c.Get("a"); ok {
		t.Fatal(`Get("a") hit; want evicted`)
	}
	if v, ok := c.Get("b"); !ok || v != "2" {
		t.Fatalf(`Get("b") = %q, %v; want "2", true`, v, ok)
	}
	c.Delete("b")
	c.Set("c", "3")
	if v, ok := c.Get("c"); !ok || v != "3" || c.Len() != 1 {
		t.Fatalf(`Get("c") = %q, %v, Len %d; want "3", true, 1`, v, ok, c.Len())
	}
}

// Command app simulates an LRU cache driven by commands on standard input.
//
// The first line holds the capacity; each later line is one of
// SET <key> <value>, GET <key>, DEL <key> or SIZE.
package main

import (
	"bufio"
	"bytes"
	"errors"
	"fmt"
	"io"
	"os"
	"strconv"

	"lru/internal/lru"
)

func main() {
	if err := run(os.Stdin, os.Stdout); err != nil {
		fmt.Fprintln(os.Stderr, "app:", err)
		os.Exit(1)
	}
}

func run(r io.Reader, w io.Writer) error {
	in := bufio.NewReaderSize(r, 1<<16)
	out := bufio.NewWriterSize(w, 1<<16)

	first, err := readLine(in)
	if err != nil {
		if errors.Is(err, io.EOF) {
			return nil
		}
		return fmt.Errorf("read capacity: %w", err)
	}
	capacity, err := strconv.Atoi(string(bytes.TrimSpace(first)))
	if err != nil || capacity < 1 {
		return fmt.Errorf("invalid capacity %q", first)
	}
	cache := lru.New(capacity)

	for {
		line, err := readLine(in)
		if err != nil {
			if errors.Is(err, io.EOF) {
				break
			}
			return fmt.Errorf("read command: %w", err)
		}
		execute(cache, line, out)
	}
	if err := out.Flush(); err != nil {
		return fmt.Errorf("write output: %w", err)
	}
	return nil
}

// execute applies one command line to the cache, writing any result to out.
// Malformed lines are ignored.
func execute(cache *lru.Cache, line []byte, out *bufio.Writer) {
	cmd, rest, _ := bytes.Cut(line, []byte{' '})
	switch string(cmd) {
	case "SET":
		key, value, ok := bytes.Cut(rest, []byte{' '})
		if !ok || len(key) == 0 || len(value) == 0 {
			return
		}
		cache.Set(string(key), string(value))
	case "GET":
		if len(rest) == 0 {
			return
		}
		if v, ok := cache.Get(string(rest)); ok {
			out.WriteString(v)
		} else {
			out.WriteString("NULL")
		}
		out.WriteByte('\n')
	case "DEL":
		if len(rest) == 0 {
			return
		}
		if cache.Delete(string(rest)) {
			out.WriteString("1\n")
		} else {
			out.WriteString("0\n")
		}
	case "SIZE":
		out.Write(strconv.AppendInt(out.AvailableBuffer(), int64(cache.Len()), 10))
		out.WriteByte('\n')
	}
}

// readLine returns the next line without its terminator (\n or \r\n).
// The returned slice is only valid until the next call. It returns io.EOF
// once the input is exhausted; a final line lacking \n is still returned.
func readLine(in *bufio.Reader) ([]byte, error) {
	line, err := in.ReadSlice('\n')
	if errors.Is(err, bufio.ErrBufferFull) {
		// Overlong line: accumulate it in full.
		buf := append([]byte(nil), line...)
		for errors.Is(err, bufio.ErrBufferFull) {
			line, err = in.ReadSlice('\n')
			buf = append(buf, line...)
		}
		line = buf
	}
	if err != nil && !errors.Is(err, io.EOF) {
		return nil, err
	}
	if len(line) == 0 && err != nil {
		return nil, io.EOF
	}
	line = bytes.TrimSuffix(line, []byte{'\n'})
	line = bytes.TrimSuffix(line, []byte{'\r'})
	return line, nil
}
